def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    balanced_groups = []  # Initialize an empty list to store the balanced groups
    stack = []
    start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                balanced_groups.append(paren_string[start:i+1])

    return balanced_groups

